# hackathon-Agentic-AI

## Voice commands

Tap a microphone button, speak, tap again. The speech is transcribed live with
[Gradium](https://docs.gradium.ai) speech-to-text and saved as a JSON command
file that an Antigravity agent can read and act on.

```
Browser (public/)  --token-->  Gradium STT (WebSocket)
       |                              |
       |  transcript                  | live text
       v                              |
server.js  --writes-->  commands/<id>.json + commands/latest.json  -->  Antigravity
```

### Run it

1. Set your Gradium API key, either as an environment variable `GRADIUM_API_KEY`
   or by copying `.env.example` to `.env` and filling it in. Never commit `.env`.
2. `npm start` (Node 20.12+, no dependencies to install)
3. Open http://localhost:3000 and allow microphone access.

### Command file format

Each recording is saved to `commands/<id>.json`, and the newest one is also
copied to `commands/latest.json`:

```json
{
  "id": "2026-10-10T11-48-48-645Z-a0ec79",
  "type": "voice_command",
  "created_at": "2026-10-10T11:48:48.645Z",
  "source": "microphone",
  "language": "en",
  "transcript": "Create a new task called Buy Groceries and set it for tomorrow morning.",
  "status": "pending"
}
```

To match the format your Antigravity agent expects, edit `buildCommand()` in
`server.js`.

### How the key stays secret

The browser never sees the API key. It asks `server.js` for a short-lived,
single-use token (`POST /api/gradium-token`) and uses that to open the
speech-to-text WebSocket.

## Entire

Agent sessions in this repo are captured with Entire. See
[ENTIRE_SETUP.md](ENTIRE_SETUP.md).
# Copy this file to .env and put your Gradium API key after the =
GRADIUM_API_KEY=
{
  "name": "voice-commands",
  "version": "1.0.0",
  "private": true,
  "description": "Tap-to-talk speech-to-text that saves JSON command files for Antigravity",
  "main": "server.js",
  "scripts": {
    "start": "node server.js"
  },
  "engines": {
    "node": ">=20.12"
  }
}
// Voice-command server: serves the front end, hands the browser short-lived
// Gradium tokens (the API key never leaves the server), and saves each
// transcription as a JSON command file in commands/ for Antigravity to pick up.
//
// No dependencies. Run with: node server.js  (Node 20.12+)

const http = require("node:http");
const fs = require("node:fs");
const path = require("node:path");
const crypto = require("node:crypto");

try {
  process.loadEnvFile(path.join(__dirname, ".env"));
} catch {
  // No .env file: rely on the real environment (e.g. cloud env variables).
}

const PORT = Number(process.env.PORT) || 3000;
const GRADIUM_API_KEY = process.env.GRADIUM_API_KEY;
const GRADIUM_BASE = process.env.GRADIUM_BASE_URL || "https://api.gradium.ai/api";
const PUBLIC_DIR = path.join(__dirname, "public");
const COMMANDS_DIR = path.join(__dirname, "commands");

const MIME = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".json": "application/json; charset=utf-8",
};

function sendJson(res, status, body) {
  res.writeHead(status, { "Content-Type": MIME[".json"] });
  res.end(JSON.stringify(body, null, 2));
}

function readBody(req, limit = 1_000_000) {
  return new Promise((resolve, reject) => {
    let data = "";
    req.on("data", (chunk) => {
      data += chunk;
      if (data.length > limit) {
        reject(new Error("Body too large"));
        req.destroy();
      }
    });
    req.on("end", () => resolve(data));
    req.on("error", reject);
  });
}

async function createToken(res) {
  if (!GRADIUM_API_KEY) {
    return sendJson(res, 500, { error: "GRADIUM_API_KEY is not set on the server" });
  }
  const response = await fetch(`${GRADIUM_BASE}/api-keys/token`, {
    headers: { "x-api-key": GRADIUM_API_KEY },
  });
  if (!response.ok) {
    return sendJson(res, 502, { error: `Could not create Gradium token (${response.status})` });
  }
  sendJson(res, 200, await response.json());
}

// The shape of a command file. Change this to match what your Antigravity
// agent expects.
function buildCommand({ transcript, language }) {
  const now = new Date();
  return {
    id: `${now.toISOString().replace(/[:.]/g, "-")}-${crypto.randomBytes(3).toString("hex")}`,
    type: "voice_command",
    created_at: now.toISOString(),
    source: "microphone",
    language: language || "en",
    transcript: transcript.trim(),
    status: "pending",
  };
}

async function saveCommand(req, res) {
  let body;
  try {
    body = JSON.parse(await readBody(req));
  } catch {
    return sendJson(res, 400, { error: "Expected a JSON body" });
  }
  if (typeof body.transcript !== "string" || !body.transcript.trim()) {
    return sendJson(res, 400, { error: "transcript must be a non-empty string" });
  }
  const command = buildCommand(body);
  fs.mkdirSync(COMMANDS_DIR, { recursive: true });
  const json = JSON.stringify(command, null, 2) + "\n";
  fs.writeFileSync(path.join(COMMANDS_DIR, `${command.id}.json`), json);
  fs.writeFileSync(path.join(COMMANDS_DIR, "latest.json"), json);
  sendJson(res, 201, command);
}

function listCommands(res) {
  if (!fs.existsSync(COMMANDS_DIR)) return sendJson(res, 200, []);
  const commands = fs
    .readdirSync(COMMANDS_DIR)
    .filter((f) => f.endsWith(".json") && f !== "latest.json")
    .sort()
    .reverse()
    .slice(0, 50)
    .map((f) => JSON.parse(fs.readFileSync(path.join(COMMANDS_DIR, f), "utf8")));
  sendJson(res, 200, commands);
}

function serveStatic(req, res) {
  const urlPath = decodeURIComponent(new URL(req.url, "http://x").pathname);
  const file = path.normalize(path.join(PUBLIC_DIR, urlPath === "/" ? "index.html" : urlPath));
  if (!file.startsWith(PUBLIC_DIR) || !fs.existsSync(file) || fs.statSync(file).isDirectory()) {
    res.writeHead(404);
    return res.end("Not found");
  }
  res.writeHead(200, { "Content-Type": MIME[path.extname(file)] || "application/octet-stream" });
  fs.createReadStream(file).pipe(res);
}

const server = http.createServer(async (req, res) => {
  try {
    const { pathname } = new URL(req.url, "http://x");
    if (req.method === "POST" && pathname === "/api/gradium-token") return await createToken(res);
    if (req.method === "POST" && pathname === "/api/commands") return await saveCommand(req, res);
    if (req.method === "GET" && pathname === "/api/commands") return listCommands(res);
    if (req.method === "GET") return serveStatic(req, res);
    res.writeHead(405);
    res.end();
  } catch (err) {
    console.error(err);
    sendJson(res, 500, { error: "Internal server error" });
  }
});

if (require.main === module) {
  server.listen(PORT, () => {
    console.log(`Voice commands running at http://localhost:${PORT}`);
    if (!GRADIUM_API_KEY) console.warn("Warning: GRADIUM_API_KEY is not set.");
  });
}

module.exports = { server, buildCommand };
// Tap-to-talk: microphone -> Gradium speech-to-text (WebSocket) -> JSON command.
// The browser only ever sees a short-lived token from our server, never the API key.

const TARGET_RATE = 24000; // Gradium "pcm" = 24 kHz, 16-bit, mono
const CHUNK_SAMPLES = 1920; // 80 ms at 24 kHz
const LANGUAGE = "en";

const micBtn = document.getElementById("mic");
const statusEl = document.getElementById("status");
const transcriptEl = document.getElementById("transcript");
const jsonEl = document.getElementById("json");

let session = null;

function setStatus(text, kind = "") {
  statusEl.textContent = text;
  statusEl.className = kind;
}

// Captures raw float samples from the microphone off the main thread.
const WORKLET_SRC = `
class Capture extends AudioWorkletProcessor {
  process(inputs) {
    const ch = inputs[0] && inputs[0][0];
    if (ch) this.port.postMessage(ch.slice(0));
    return true;
  }
}
registerProcessor("capture", Capture);
`;

function resample(input, fromRate, toRate) {
  if (fromRate === toRate) return input;
  const ratio = fromRate / toRate;
  const out = new Float32Array(Math.floor(input.length / ratio));
  for (let i = 0; i < out.length; i++) {
    const pos = i * ratio;
    const idx = Math.floor(pos);
    const frac = pos - idx;
    const next = idx + 1 < input.length ? input[idx + 1] : input[idx];
    out[i] = input[idx] + (next - input[idx]) * frac;
  }
  return out;
}

function toPcm16Base64(float32) {
  const pcm = new Int16Array(float32.length);
  for (let i = 0; i < float32.length; i++) {
    const s = Math.max(-1, Math.min(1, float32[i]));
    pcm[i] = s < 0 ? s * 32768 : s * 32767;
  }
  const bytes = new Uint8Array(pcm.buffer);
  let binary = "";
  for (let i = 0; i < bytes.length; i += 0x8000) {
    binary += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
  }
  return btoa(binary);
}

async function getToken() {
  const res = await fetch("/api/gradium-token", { method: "POST" });
  const body = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(body.error || "Could not get a Gradium token");
  return body.token;
}

async function start() {
  micBtn.disabled = true;
  setStatus("Connecting…");

  const token = await getToken();
  const stream = await navigator.mediaDevices.getUserMedia({
    audio: { channelCount: 1, echoCancellation: true, noiseSuppression: true },
  });

  const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  const workletUrl = URL.createObjectURL(new Blob([WORKLET_SRC], { type: "text/javascript" }));
  await audioCtx.audioWorklet.addModule(workletUrl);
  const source = audioCtx.createMediaStreamSource(stream);
  const node = new AudioWorkletNode(audioCtx, "capture");
  const mute = audioCtx.createGain();
  mute.gain.value = 0;

  const url = new URL("wss://api.gradium.ai/api/speech/asr");
  url.searchParams.set("token", token);
  const ws = new WebSocket(url);

  const segments = [];
  const baseText = transcriptEl.value.trim();
  let pending = new Float32Array(0);
  let ready = false;
  let finished;
  const done = new Promise((resolve) => (finished = resolve));

  ws.onopen = () => {
    ws.send(JSON.stringify({
      type: "setup",
      model_name: "default",
      input_format: "pcm",
      json_config: { language: LANGUAGE },
    }));
  };

  ws.onmessage = (event) => {
    const msg = JSON.parse(event.data);
    if (msg.type === "ready") {
      ready = true;
      micBtn.disabled = false;
      micBtn.classList.add("recording");
      micBtn.setAttribute("aria-label", "Stop recording");
      setStatus("Listening… tap to stop");
    } else if (msg.type === "text") {
      segments.push(msg.text);
      transcriptEl.value = [baseText, segments.join(" ")].filter(Boolean).join(" ");
    } else if (msg.type === "end_of_stream") {
      finished();
    } else if (msg.type === "error") {
      setStatus(`Gradium error: ${msg.message || "unknown"}`, "error");
      finished();
    }
  };
  ws.onerror = () => setStatus("Connection error", "error");
  ws.onclose = () => finished();

  node.port.onmessage = (event) => {
    if (!ready || ws.readyState !== WebSocket.OPEN) return;
    const samples = resample(event.data, audioCtx.sampleRate, TARGET_RATE);
    const merged = new Float32Array(pending.length + samples.length);
    merged.set(pending);
    merged.set(samples, pending.length);
    let offset = 0;
    while (merged.length - offset >= CHUNK_SAMPLES) {
      const chunk = merged.subarray(offset, offset + CHUNK_SAMPLES);
      ws.send(JSON.stringify({ type: "audio", audio: toPcm16Base64(chunk) }));
      offset += CHUNK_SAMPLES;
    }
    pending = merged.slice(offset);
  };

  source.connect(node);
  node.connect(mute).connect(audioCtx.destination);

  session = {
    async stop() {
      micBtn.disabled = true;
      micBtn.classList.remove("recording");
      setStatus("Finishing transcription…");
      source.disconnect();
      node.disconnect();
      stream.getTracks().forEach((t) => t.stop());
      if (ws.readyState === WebSocket.OPEN) {
        if (pending.length) ws.send(JSON.stringify({ type: "audio", audio: toPcm16Base64(pending) }));
        ws.send(JSON.stringify({ type: "end_of_stream" }));
      }
      await Promise.race([done, new Promise((r) => setTimeout(r, 5000))]);
      ws.close();
      audioCtx.close();
      URL.revokeObjectURL(workletUrl);
    },
  };
}

async function saveCommand() {
  const transcript = transcriptEl.value.trim();
  if (!transcript) {
    setStatus("Nothing to save — say something first", "error");
    return;
  }
  const res = await fetch("/api/commands", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ transcript, language: LANGUAGE }),
  });
  const body = await res.json();
  if (!res.ok) throw new Error(body.error || "Could not save the command");
  jsonEl.textContent = JSON.stringify(body, null, 2);
  setStatus(`Saved commands/${body.id}.json`, "ok");
}

micBtn.addEventListener("click", async () => {
  try {
    if (session) {
      const s = session;
      session = null;
      await s.stop();
      micBtn.setAttribute("aria-label", "Start recording");
      micBtn.disabled = false;
      await saveCommand();
    } else {
      await start();
    }
  } catch (err) {
    console.error(err);
    session = null;
    micBtn.disabled = false;
    micBtn.classList.remove("recording");
    setStatus(err.message || String(err), "error");
  }
});

document.getElementById("save").addEventListener("click", () =>
  saveCommand().catch((err) => setStatus(err.message, "error")));

document.getElementById("clear").addEventListener("click", () => {
  transcriptEl.value = "";
  setStatus("Ready");
});
